(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-963":{scenario:{company:"Song Lam Power Distribution",supervisor:{name:"Bùi Quốc Trung",role:{vi:"Điều độ viên trưởng ca",en:"Shift Control Supervisor"}},ref_code:"DMS-472-1104",title:{vi:"Khoanh đúng đoạn sự cố. Chuyển tải trong giới hạn. An toàn trước tiên.",en:"Isolate the right section. Transfer within limits. Safety first."},brief:{vi:"Tuyến 22 kV số 472 cắt máy cắt đầu tuyến sau khi tự đóng lại không thành công. Bạn lập phiếu thao tác DMS-472-1104: xác định đoạn sự cố theo chỉ báo sự cố (FPI), cô lập, cấp điện lại đầu tuyến và chuyển phần hạ lưu sang tuyến 474 qua dao liên lạc. Phụ tải trước sự cố: S12-15 60 A, S15-18 85 A, S18-21 55 A; tuyến 474 đang mang 210 A, giới hạn 380 A (mô phỏng). Sửa đoạn sự cố và dòng tuyến 474 sau chuyển tải, rồi lập báo cáo có căn cứ.",en:"Feeder 472 (22 kV) tripped at the source breaker after failed auto-reclosing. Prepare switching order DMS-472-1104: locate the faulted section from the fault passage indicators (FPI), isolate it, restore the upstream part and move the downstream part to feeder 474 via the tie switch. Pre-fault loads: S12-15 60 A, S15-18 85 A, S18-21 55 A; feeder 474 carries 210 A, limit 380 A (training data). Correct the faulted section and feeder 474 current after transfer, then write an evidence-based report."},reference_title:{vi:"Bản ghi FPI & sơ đồ phụ tải đã xác nhận · Tuyến 472",en:"Confirmed FPI record & load diagram · Feeder 472"},fields:[{id:"FAULT_SEG",label:{vi:"Đoạn sự cố cần cô lập",en:"Faulted section to isolate"},initial:"S15-18",expected:"S12-15",choices:["S09-12","S12-15","S15-18"],reference:"Bản ghi chỉ báo sự cố FPI",hint:{vi:"Sự cố nằm giữa FPI cuối cùng có dòng sự cố đi qua và FPI đầu tiên không ghi nhận dòng sự cố.",en:"The fault lies between the last FPI that saw fault current and the first FPI that did not."}},{id:"F474_AMP",label:{vi:"Dòng tuyến 474 sau chuyển tải (A)",en:"Feeder 474 current after transfer (A)"},initial:"410",expected:"350",reference:"Sơ đồ phụ tải trước sự cố",ref_value:{vi:"Tuyến 474 đang 210 A; S12-15 60 A; S15-18 85 A; S18-21 55 A",en:"Feeder 474 at 210 A; S12-15 60 A; S15-18 85 A; S18-21 55 A"},hint:{vi:"Đoạn sự cố đã cô lập không được cấp điện nên không cộng vào phụ tải chuyển sang tuyến 474.",en:"The isolated faulted section stays de-energised, so its load is not transferred to feeder 474."}}],sop32:{vi:"Dòng tuyến nhận = dòng hiện tại + tổng phụ tải các đoạn hạ lưu sau điểm cô lập (không gồm đoạn sự cố); chỉ đóng dao liên lạc khi kết quả không vượt giới hạn mang tải.",en:"Receiving feeder current = present current + loads of downstream sections beyond the isolation point (excluding the faulted section); close the tie only if the result stays within the limit."},context:{label:"DMS-SCADA / F472",metrics:[{label:{vi:"Tuyến 474 hiện tại",en:"Feeder 474 now"},value:"210 A"},{label:{vi:"Giới hạn tuyến 474",en:"Feeder 474 limit"},value:"380 A"},{label:{vi:"Cấp điện áp",en:"Voltage level"},value:"22 kV"}]},crisis:{vi:"Đội trưởng sửa chữa gọi: “Cho anh em leo cột làm luôn cho nhanh, phiếu công tác với tiếp địa tính sau. Khu công nghiệp đang gọi phàn nàn liên tục.”",en:"The repair crew leader calls: “Let the lads climb and start now, the work permit and earthing can come later. The industrial park keeps calling to complain.”"},options:{safe:{vi:"Không cho làm việc khi chưa cắt điện, kiểm tra không còn điện, đặt tiếp địa và cấp phiếu công tác; báo điều độ viên trưởng ca; trong lúc chờ, chuyển tải hạ lưu sang tuyến 474 để giảm khách hàng mất điện.",en:"Allow no work until the section is switched out, proven dead, earthed and covered by a work permit; inform the shift supervisor; meanwhile transfer the downstream load to feeder 474 to cut outage numbers."},shortcut:{vi:"Cho đội leo cột sửa ngay, bổ sung phiếu công tác và tiếp địa sau khi xong việc.",en:"Let the crew climb and repair now and add the permit and earthing afterwards."},wait:{vi:"Không trả lời đội sửa chữa và chờ lãnh đạo tự quyết định.",en:"Do not answer the crew and wait for management to decide."}},questions:{vi:["Vì sao đoạn sự cố là S12-15 và tuyến 474 sau chuyển tải là 350 A? Dữ liệu nào trong terminal chứng minh?","Trình bày trình tự biện pháp an toàn bắt buộc trước khi cho đội sửa chữa làm việc trên đoạn S12-15."],en:["Why is the faulted section S12-15 and why is feeder 474 at 350 A after transfer? Which terminal data proves it?","Set out the mandatory safety sequence before the repair crew may work on section S12-15."]},hints:{vi:["Chạy cat fpi.log và tìm ranh giới giữa FPI có dòng sự cố và FPI không ghi nhận.","Chỉ cộng các đoạn hạ lưu được cấp điện lại qua dao liên lạc vào dòng tuyến 474 theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không làm việc trên lưới khi chưa đủ biện pháp an toàn và phiếu công tác."],en:["Run cat fpi.log and find the boundary between FPIs that saw fault current and those that did not.","Add only the downstream sections re-energised via the tie switch to feeder 474 as in SOP 3.2.","Re-read SOP 4.2: no work on the network without full safety measures and a work permit."]},terminal:{system:"dms-scada",settable:["FAULT_SEG","F474_AMP"],commands:[{cmd:"status",out:{vi:"Tuyến 472: máy cắt đầu tuyến mở sau tự đóng lại không thành · LBS-09, LBS-12, LBS-15, LBS-18 đang đóng · dao liên lạc TIE-472/474 mở",en:"Feeder 472: source breaker open after failed reclosing · LBS-09, LBS-12, LBS-15, LBS-18 closed · tie switch TIE-472/474 open"}},{cmd:"cat fpi.log",out:{vi:"FPI-09: có dòng sự cố · FPI-12: có dòng sự cố · FPI-15: không ghi nhận · FPI-18: không ghi nhận",en:"FPI-09: fault current seen · FPI-12: fault current seen · FPI-15: none · FPI-18: none"}},{cmd:"cat load.txt",out:{vi:"Phụ tải trước sự cố: S12-15 = 60 A · S15-18 = 85 A · S18-21 (cuối tuyến) = 55 A",en:"Pre-fault loads: S12-15 = 60 A · S15-18 = 85 A · S18-21 (feeder end) = 55 A"}},{cmd:"cat feeder474.txt",out:{vi:"Tuyến 474: dòng hiện tại 210 A · giới hạn mang tải cho phép 380 A (mô phỏng) · điện áp cuối tuyến trong giới hạn",en:"Feeder 474: present current 210 A · permitted loading limit 380 A (training data) · end-of-feeder voltage within limits"}},{cmd:"cat crew.log",out:{vi:"Đội sửa chữa đã đến cột 472/14 · chưa có phiếu công tác · chưa đặt tiếp địa di động",en:"Repair crew at pole 472/14 · no work permit issued · portable earths not yet applied"}}]}},learning:{summary:{vi:"Kỹ sư vận hành lưới điện phân phối giám sát và điều khiển lưới trung, hạ áp qua hệ thống SCADA/DMS: thao tác đóng cắt, xử lý sự cố, cô lập và khôi phục cấp điện, điều chỉnh điện áp, phối hợp đội sửa chữa. Nghề quyết định độ tin cậy cung cấp điện (SAIDI, SAIFI) và an toàn của người làm việc trên lưới; đòi hỏi hiểu sơ đồ lưới, rơ le bảo vệ, tính toán phụ tải và kỷ luật quy trình tuyệt đối.",en:"A power distribution network operator monitors and controls the medium and low voltage network through SCADA/DMS: switching, fault handling, isolation and restoration, voltage control and coordination of repair crews. The role drives supply reliability (SAIDI, SAIFI) and the safety of people working on the network; it requires network diagrams, protection relays, load calculations and absolute procedural discipline."},responsibilities:{vi:["Giám sát trạng thái lưới, phụ tải, điện áp trên SCADA/DMS theo ca.","Lập và thực hiện phiếu thao tác đóng cắt theo kế hoạch và khi có sự cố.","Xác định vị trí sự cố, cô lập đoạn hỏng và khôi phục cấp điện cho phần còn lại.","Cấp phép, phối hợp và giám sát biện pháp an toàn cho đội công tác trên lưới.","Ghi nhật ký vận hành, thống kê sự cố và chỉ số độ tin cậy cung cấp điện."],en:["Monitor network status, load and voltage on SCADA/DMS each shift.","Prepare and execute switching orders for planned work and faults.","Locate faults, isolate damaged sections and restore supply to the rest.","Issue permits and coordinate and supervise safety measures for field crews.","Keep the operating log and track faults and reliability indices."]},competencies:[{name:{vi:"Đọc sơ đồ & SCADA",en:"Diagrams & SCADA"},desc:{vi:"Đọc nhanh sơ đồ một sợi, trạng thái thiết bị và cảnh báo trên màn hình điều độ.",en:"Read single-line diagrams, device states and alarms on the control screen quickly."}},{name:{vi:"Xử lý sự cố & khôi phục",en:"Fault handling & restoration"},desc:{vi:"Dùng FPI, rơ le và recloser để khoanh vùng sự cố, khôi phục điện nhanh và an toàn.",en:"Use FPIs, relays and reclosers to locate faults and restore supply quickly and safely."}},{name:{vi:"Tính toán phụ tải & điện áp",en:"Load & voltage calculation"},desc:{vi:"Kiểm tra giới hạn mang tải, sụt áp trước khi chuyển tải giữa các tuyến.",en:"Check loading limits and voltage drop before transferring load between feeders."}},{name:{vi:"An toàn điện",en:"Electrical safety"},desc:{vi:"Thực hiện đúng trình tự cắt điện, kiểm tra không điện, tiếp địa, rào chắn, biển báo.",en:"Apply the sequence: switch out, prove dead, earth, barrier and sign."}},{name:{vi:"Giao tiếp điều độ",en:"Control room communication"},desc:{vi:"Ra lệnh rõ ràng, nhắc lại lệnh, ghi âm và ghi nhật ký đầy đủ.",en:"Give clear instructions, use repeat-back, record calls and keep full logs."}}],knowledge:{vi:["Luật Điện lực và quy định hiện hành về vận hành hệ thống điện phân phối.","Quy định hiện hành của Bộ Công Thương về an toàn điện: cắt điện, kiểm tra không còn điện, tiếp địa, rào chắn, biển báo.","Chỉ số độ tin cậy SAIDI, SAIFI, MAIFI theo IEEE 1366.","Tự động hóa lưới phân phối: FLISR, recloser, dao phụ tải, chỉ báo sự cố (FPI).","IEC 61850 về truyền thông trong trạm biến áp và tự động hóa lưới."],en:["The Electricity Law and current rules on distribution system operation.","Current Ministry of Industry and Trade electrical safety rules: switching out, proving dead, earthing, barriers and signs.","Reliability indices SAIDI, SAIFI and MAIFI under IEEE 1366.","Distribution automation: FLISR, reclosers, load break switches and fault passage indicators (FPI).","IEC 61850 on substation communication and network automation."]},tools:["Hệ thống SCADA/DMS","Sơ đồ một sợi lưới phân phối","Phần mềm tính toán trào lưu công suất","Hệ thống quản lý mất điện (OMS)","Thiết bị kiểm tra không còn điện"],kpis:{vi:["SAIDI, SAIFI của khu vực phụ trách so với mục tiêu.","Thời gian khôi phục điện trung bình cho phần lưới không sự cố.","Số thao tác nhầm, vi phạm an toàn (mục tiêu bằng 0).","Tỷ lệ phiếu thao tác lập đúng, đủ ngay lần đầu."],en:["SAIDI and SAIFI for the area versus target.","Average restoration time for healthy network sections.","Switching errors and safety violations (target zero).","Share of switching orders correct and complete first time."]},day:[{time:"06:45",vi:"Nhận ca, đọc nhật ký vận hành và danh sách phiếu công tác đang mở.",en:"Take over the shift and read the operating log and open work permits."},{time:"08:00",vi:"Thực hiện thao tác cắt điện theo kế hoạch bảo trì tuyến.",en:"Carry out planned switching for feeder maintenance."},{time:"10:30",vi:"Xử lý sự cố tuyến: khoanh vùng theo FPI, cô lập và khôi phục cấp điện.",en:"Handle a feeder fault: locate by FPI, isolate and restore supply."},{time:"14:00",vi:"Cấp phép và giám sát biện pháp an toàn cho đội công tác trên lưới.",en:"Issue permits and supervise safety measures for crews on the network."},{time:"18:00",vi:"Bàn giao ca, cập nhật thống kê sự cố và chỉ số độ tin cậy.",en:"Hand over the shift and update fault statistics and reliability indices."}],mistakes:{vi:["Đọc sai chỉ báo sự cố, cô lập nhầm đoạn lưới và đóng điện vào điểm sự cố.","Cộng cả phụ tải đoạn sự cố khi tính chuyển tải, bỏ lỡ cơ hội khôi phục điện.","Cho phép làm việc khi chưa tiếp địa, chưa có phiếu công tác vì áp lực thời gian."],en:["Misreading fault indicators, isolating the wrong section and re-energising onto the fault.","Including the faulted section's load in the transfer check and missing a chance to restore supply.","Allowing work before earthing and a work permit because of time pressure."]},career:[{vi:"Nhân viên trực vận hành trạm biến áp",en:"Substation operator"},{vi:"Điều độ viên lưới điện phân phối",en:"Distribution network controller"},{vi:"Điều độ viên trưởng ca",en:"Shift control supervisor"},{vi:"Trưởng phòng điều độ",en:"Head of network control"}],glossary:[{term:"SCADA/DMS",vi:"Hệ thống giám sát, điều khiển và quản lý lưới phân phối từ trung tâm điều độ.",en:"Supervisory control and distribution management system run from the control centre."},{term:"FPI",vi:"Chỉ báo sự cố: thiết bị trên đường dây báo có dòng sự cố đi qua vị trí đặt.",en:"Fault passage indicator: a line device showing that fault current passed its location."},{term:"Recloser",vi:"Thiết bị tự đóng lại: tự cắt khi sự cố và đóng lại để loại trừ sự cố thoáng qua.",en:"Device that trips on a fault and recloses to clear transient faults."},{term:"SAIDI",vi:"Thời gian mất điện trung bình của một khách hàng trong kỳ báo cáo.",en:"Average outage duration per customer over the reporting period."},{term:"Phiếu công tác",vi:"Văn bản cho phép làm việc trên thiết bị điện, ghi rõ phạm vi và biện pháp an toàn.",en:"Work permit authorising work on electrical equipment with defined scope and safety measures."}],quiz:[{q:{vi:"FPI-06 và FPI-09 ghi nhận dòng sự cố, FPI-12 thì không. Sự cố nằm ở đâu?",en:"FPI-06 and FPI-09 saw fault current, FPI-12 did not. Where is the fault?"},options:{vi:["Giữa FPI-06 và FPI-09","Giữa FPI-09 và FPI-12","Sau FPI-12","Trước FPI-06"],en:["Between FPI-06 and FPI-09","Between FPI-09 and FPI-12","Beyond FPI-12","Before FPI-06"]},answer:1,explain:{vi:"Sự cố nằm sau FPI cuối cùng có dòng sự cố (FPI-09) và trước FPI đầu tiên không ghi nhận (FPI-12).",en:"The fault is beyond the last FPI with fault current (FPI-09) and before the first without it (FPI-12)."}},{q:{vi:"Tuyến nhận đang 200 A, giới hạn 350 A; cần chuyển hai đoạn hạ lưu 70 A và 60 A. Dòng sau chuyển tải là bao nhiêu?",en:"The receiving feeder carries 200 A with a 350 A limit; two downstream sections of 70 A and 60 A are transferred. What is the new current?"},options:{vi:["200 A","350 A","330 A","130 A"],en:["200 A","350 A","330 A","130 A"]},answer:2,explain:{vi:"Dòng sau chuyển tải = 200 + 70 + 60 = 330 A, vẫn dưới giới hạn 350 A.",en:"New current = 200 + 70 + 60 = 330 A, still below the 350 A limit."}},{q:{vi:"Đội sửa chữa muốn làm việc ngay khi chưa tiếp địa. Bạn làm gì?",en:"The repair crew wants to start before earthing. What do you do?"},options:{vi:["Đồng ý nếu máy cắt đã mở","Yêu cầu làm nhanh","Không trả lời","Không cấp phép đến khi đủ biện pháp an toàn và phiếu công tác"],en:["Agree if the breaker is open","Tell them to be quick","Do not answer","No permit until all safety measures and the work permit are in place"]},answer:3,explain:{vi:"Điện áp cảm ứng, đóng nhầm hoặc nguồn ngược có thể gây chết người; tiếp địa và phiếu công tác là bắt buộc.",en:"Induced voltage, wrong switching or backfeed can kill; earthing and a work permit are mandatory."}},{q:{vi:"SAIDI đo lường điều gì?",en:"What does SAIDI measure?"},options:{vi:["Thời gian mất điện trung bình của một khách hàng trong kỳ","Số lần mất điện thoáng qua","Tổn thất điện năng","Điện áp trung bình"],en:["Average outage duration per customer in the period","Number of momentary interruptions","Energy losses","Average voltage"]},answer:0,explain:{vi:"SAIDI bằng tổng số phút mất điện của khách hàng chia cho tổng số khách hàng được phục vụ.",en:"SAIDI equals total customer interruption minutes divided by total customers served."}}],tools_en:["SCADA/DMS system","Distribution network single-line diagram","Power flow calculation software","Outage management system (OMS)","Absence of voltage tester"]}}})})(window.KKR);
